NS_IMETHODIMP StoreIndexer::OnStartMessage(nsACString const& token,
                                           nsACString const& envAddr,
                                           PRTime envDate) {
  MOZ_ASSERT(!mParser);  // Can't be mid-message!

  mStoreToken = token;

  // Start a new header parser for this message...
  mParser = new nsParseMailMessageState();
  nsresult rv = mParser->SetMailDB(mDB);
  NS_ENSURE_SUCCESS(rv, rv);
  rv = mParser->SetBackupMailDB(mBackupDB);
  NS_ENSURE_SUCCESS(rv, rv);

  mParser->SetEnvDetails(envAddr, envDate);

uint32_t rcvTimeSecs = 0;
PRTime datePRTime = m_EnvDate;
if (date) {
  // Date:
  nsAutoCString dateStr(date->value, date->length);
  if (PR_ParseTimeString(dateStr.get(), false, &datePRTime) ==
      PR_SUCCESS) {
    // Convert to seconds as default value for 'Received'.
    PRTime2Seconds(datePRTime, &rcvTimeSecs);

if (datePRTime == 0) {
  // If there was some problem parsing the Date header *AND* we
  // couldn't get a valid envelope date *AND* we couldn't get a valid
  // Received: header date, use now as the time.
  // This doesn't affect local (POP3) messages, because we use the
  // envelope date if there's no Date: header, but it will affect IMAP
  // msgs w/o a Date: header or Received: headers.
  datePRTime = PR_Now();
}
m_newMsgHdr->SetDate(datePRTime);
